import { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

const RecipePage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [recipe, setRecipe] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [hashtags, setHashtags] = useState([]);

    const extractHashtags = (content) => {
        const tags = content.match(/#\w+/g) || [];
        return [...new Set(tags)];
    };

    const handleTagClick = (tag) => {
        // Navigate to homepage with search query in state
        navigate('/', {
            state: { searchTerm: tag },
            replace: true
        });
    };

    useEffect(() => {
        const fetchRecipe = async () => {
            try {
                setLoading(true);
                setError(null);

                const markdownModule = await import(`../recipes/${id}.md`);
                const response = await fetch(markdownModule.default);
                const content = await response.text();

                if (content.startsWith('<!DOCTYPE html>') || content.includes('<html>')) {
                    throw new Error('Server returned HTML instead of markdown');
                }

                const titleMatch = content.match(/^#\s(.+)/m);
                const title = titleMatch ? titleMatch[1] : id.replace(/-/g, ' ');

                setRecipe({
                    title,
                    content
                });
                setHashtags(extractHashtags(content));
            } catch (err) {
                console.error('Failed to load recipe:', err);
                setError(err.message);
                setRecipe(null);
            } finally {
                setLoading(false);
            }
        };

        fetchRecipe();
    }, [id]);

    // Custom component for hashtags in markdown
    const CustomParagraph = ({ node, children, ...props }) => {
        if (typeof children[0] === 'string' && children[0].match(/#\w+/)) {
            return (
                <p style={{ lineHeight: '1.6', marginBottom: '15px' }}>
                    {children.map((child, i) => {
                        if (typeof child === 'string') {
                            return child.split(/(#\w+)/).map((part, j) => {
                                if (part.match(/#\w+/)) {
                                    return (
                                        <button
                                            key={j}
                                            onClick={(e) => {
                                                e.preventDefault();
                                                handleTagClick(part);
                                            }}
                                            style={{
                                                background: '#8FCB9B',
                                                padding: '2px 6px',
                                                borderRadius: '4px',
                                                marginRight: '5px',
                                                fontSize: '0.9em',
                                                color: '#fff',
                                                border: 'none',
                                                cursor: 'pointer'
                                            }}
                                        >
                                            {part}
                                        </button>
                                    );
                                }
                                return part;
                            });
                        }
                        return child;
                    })}
                </p>
            );
        }
        return <p style={{ lineHeight: '1.6', marginBottom: '15px' }} {...props}>{children}</p>;
    };

    if (loading) return <div style={{ textAlign: 'center', padding: '40px' }}>Loading recipe...</div>;
    if (error) return (
        <div style={{ textAlign: 'center', padding: '40px' }}>
            <h2>Recipe Not Found</h2>
            <p>We couldn't find the recipe you're looking for.</p>
            <button
                onClick={() => navigate('/')}
                style={{
                    padding: '10px 20px',
                    background: '#2c7be5',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer'
                }}
            >
                Back to All Recipes
            </button>
        </div>
    );

    return (
        <div className='container' style={{ maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
            <button
                onClick={() => navigate(-1)}
            >
                Back
            </button>

            <article>
                {hashtags.length > 0 && (
                    <div style={{ margin: '20px 0px' }}>
                        {hashtags.map(tag => (
                            <button
                                key={tag}
                                onClick={() => handleTagClick(tag)}
                                style={{
                                    display: 'inline-block',
                                    background: '#8FCB9B',
                                    padding: '6px 8px',
                                    borderRadius: '4px',
                                    marginRight: '5px',
                                    marginBottom: '5px',
                                    fontSize: '0.8em',
                                    color: '#fff9f0',
                                    border: 'none',
                                    cursor: 'pointer',
                                    boxShadow: 'none'
                                }}
                            >
                                {tag}
                            </button>
                        ))}
                    </div>
                )}

                <ReactMarkdown
                    remarkPlugins={[remarkGfm]}
                    components={{
                        h1: ({ node, ...props }) => <h1 style={{
                            borderBottom: '2px solid #666',
                            paddingBottom: '10px',
                            marginBottom: '25px'
                        }} {...props} />,
                        h2: ({ node, ...props }) => <h2 style={{
                            marginTop: '30px',
                            marginBottom: '15px'
                        }} {...props} />,
                        ul: ({ node, ...props }) => <ul style={{
                            lineHeight: '1.6',
                            marginBottom: '20px'
                        }} {...props} />,
                        ol: ({ node, ...props }) => <ol style={{
                            lineHeight: '1.6',
                            marginBottom: '20px'
                        }} {...props} />,
                        li: ({ node, ...props }) => <li style={{
                            marginBottom: '8px'
                        }} {...props} />,
                        p: CustomParagraph,
                        img: ({ node, ...props }) => <img
                            style={{
                                maxWidth: '100%',
                                borderRadius: '4px',
                                margin: '20px 0'
                            }}
                            {...props}
                        />
                    }}
                >
                    {recipe?.content}
                </ReactMarkdown>
            </article>
        </div>
    );
};

export default RecipePage;